#!/usr/bin/env python3
"""Offline compiler and resumable Key-Segment packet stream matcher."""

import base64
import json
import sys

try:
    sys.set_int_max_str_digits(8192)
except AttributeError:
    pass

MAX_TIME = (1 << 53) - 1
MAX_FLOW = (1 << 31) - 1
MIN_PRIORITY = -(1 << 31)


class Invalid(Exception):
    pass


def _pairs_no_duplicates(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise Invalid()
        result[key] = value
    return result


def _bad_constant(_value):
    raise Invalid()


def _loads(text):
    return json.loads(text, object_pairs_hook=_pairs_no_duplicates,
                      parse_constant=_bad_constant)


def _check_depth(value, maximum=64):
    # Count objects and arrays, with the outermost container at level one.
    stack = [(value, 1)]
    while stack:
        item, depth = stack.pop()
        if isinstance(item, dict):
            if depth > maximum:
                raise Invalid()
            for child in item.values():
                if isinstance(child, (dict, list)):
                    stack.append((child, depth + 1))
        elif isinstance(item, list):
            if depth > maximum:
                raise Invalid()
            for child in item:
                if isinstance(child, (dict, list)):
                    stack.append((child, depth + 1))


def _integer(value, low, high):
    return type(value) is int and low <= value <= high


def _exact_keys(value, keys):
    return type(value) is dict and set(value) == keys


def _validate_fallback(tree, width):
    count = 0

    def visit(node, depth):
        nonlocal count
        if depth > 16 or type(node) is not dict:
            raise Invalid()
        count += 1
        if count > 255:
            raise Invalid()
        keys = set(node)
        if keys == {"class"}:
            if not _integer(node["class"], 0, 65535):
                raise Invalid()
            return
        if keys != {"feature", "threshold", "le", "gt"}:
            raise Invalid()
        if not _integer(node["feature"], 0, width - 1):
            raise Invalid()
        if not _integer(node["threshold"], -2048, 2048):
            raise Invalid()
        visit(node["le"], depth + 1)
        visit(node["gt"], depth + 1)

    visit(tree, 0)


def _validate_config(config):
    if not _exact_keys(config, {"version", "idle_timeout", "packet_limit",
                                "prefix_width", "rules", "fallback"}):
        raise Invalid()
    if not _integer(config["version"], 1, 1):
        raise Invalid()
    if not _integer(config["idle_timeout"], 0, 1000000000):
        raise Invalid()
    if not _integer(config["packet_limit"], 1, 1000000000):
        raise Invalid()
    width = config["prefix_width"]
    if not _integer(width, 1, 32):
        raise Invalid()
    rules = config["rules"]
    if type(rules) is not list or len(rules) > 2048:
        raise Invalid()
    identifiers = set()
    positions = 0
    for rule in rules:
        if not _exact_keys(rule, {"id", "class", "priority", "ranges"}):
            raise Invalid()
        rid = rule["id"]
        if not _integer(rid, 0, MAX_FLOW) or rid in identifiers:
            raise Invalid()
        identifiers.add(rid)
        if not _integer(rule["class"], 0, 65535):
            raise Invalid()
        if not _integer(rule["priority"], MIN_PRIORITY, MAX_FLOW):
            raise Invalid()
        ranges = rule["ranges"]
        if type(ranges) is not list or not 1 <= len(ranges) <= 32:
            raise Invalid()
        positions += len(ranges)
        if positions > 16384:
            raise Invalid()
        for interval in ranges:
            if type(interval) is not list or len(interval) != 2:
                raise Invalid()
            low, high = interval
            if (not _integer(low, -2048, 2048) or
                    not _integer(high, -2048, 2048) or low > high):
                raise Invalid()
    _validate_fallback(config["fallback"], width)


def _encode_int(value):
    return format(value, "x")


def _compile(config):
    _check_depth(config)
    _validate_config(config)
    width = config["prefix_width"]

    # A bit is assigned to every position of every rule.  Rules are laid out
    # in rule-ID order, so increasing terminal bit numbers also give the
    # required match output order.
    ordered = sorted(config["rules"], key=lambda rule: rule["id"])
    compiled_rules = []
    first_mask = 0
    terminal_mask = 0
    position_count = 0
    for rule in ordered:
        base = position_count
        length = len(rule["ranges"])
        position_count += length
        first_mask |= 1 << base
        terminal = base + length - 1
        terminal_mask |= 1 << terminal
        compiled_rules.append([rule["id"], rule["class"], rule["priority"],
                               length, terminal])

    encoded_accept = []
    if position_count:
        # Transpose all range tests into one integer mask per possible signed
        # feature.  Difference updates avoid iterating over range widths.
        differences = [0] * 4098
        base = 0
        for rule in ordered:
            for low, high in rule["ranges"]:
                bit = 1 << base
                base += 1
                differences[low + 2048] += bit
                if high < 2048:
                    differences[high + 2049] -= bit
        byte_count = (position_count + 7) // 8
        current = 0
        for index in range(4097):
            current += differences[index]
            encoded_accept.append(base64.b64encode(
                current.to_bytes(byte_count, "big")).decode("ascii"))

    return {
        "v": 1,
        "t": config["idle_timeout"],
        "l": config["packet_limit"],
        "w": width,
        "p": position_count,
        "first": _encode_int(first_mask),
        "terminal": _encode_int(terminal_mask),
        "accept": encoded_accept,
        "rules": compiled_rules,
        "fallback": config["fallback"],
    }


def _compile_main():
    try:
        raw = sys.stdin.buffer.read(5 * 1024 * 1024 + 1)
        if len(raw) > 5 * 1024 * 1024:
            raise Invalid()
        config = _loads(raw.decode("utf-8"))
        program = _compile(config)
    except (Invalid, ValueError, TypeError, KeyError, IndexError,
            UnicodeError, json.JSONDecodeError, RecursionError, OverflowError):
        sys.stdout.write('{"error":"config"}')
        return 2
    output = json.dumps(program, sort_keys=True, separators=(",", ":"),
                        ensure_ascii=True)
    sys.stdout.write(output)
    return 0


class Flow:
    __slots__ = ("id", "last", "n", "matches", "forward", "prefix",
                 "state", "cls", "reason", "rule", "heap_index")

    def __init__(self, flow_id, time):
        self.id = flow_id
        self.last = time
        self.n = 0
        self.matches = 0
        self.forward = None
        self.prefix = []
        self.state = 0
        self.cls = None
        self.reason = None
        self.rule = None
        self.heap_index = -1


class Engine:
    def __init__(self, program):
        self.timeout = program["t"]
        self.packet_limit = program["l"]
        self.width = program["w"]
        self.position_count = program["p"]
        self.first_mask = int(program["first"], 16)
        self.terminal_mask = int(program["terminal"], 16)
        if self.position_count:
            byte_count = (self.position_count + 7) // 8
            # from_bytes also accepts the fixed-width big-endian encoding;
            # keeping this conversion explicit makes restart state portable.
            self.accept = [int.from_bytes(base64.b64decode(item), "big")
                           for item in program["accept"]]
        else:
            self.accept = []
        self.rules = program["rules"]
        self.terminal_to_rule = {rule[4]: index
                                 for index, rule in enumerate(self.rules)}
        self.fallback = program["fallback"]
        self.now = None
        self.flows = {}
        self.heap = []
        self.started = False

    # Indexed min-heap of all open, undecided flows, ordered by activity then
    # ID.  Expired decisions are sorted separately, as required by the spec.
    @staticmethod
    def _less(left, right):
        if left.last != right.last:
            return left.last < right.last
        return left.id < right.id

    def _heap_up(self, index):
        heap = self.heap
        item = heap[index]
        while index:
            parent = (index - 1) // 2
            if not self._less(item, heap[parent]):
                break
            heap[index] = heap[parent]
            heap[index].heap_index = index
            index = parent
        heap[index] = item
        item.heap_index = index

    def _heap_down(self, index):
        heap = self.heap
        size = len(heap)
        item = heap[index]
        while True:
            child = index * 2 + 1
            if child >= size:
                break
            if child + 1 < size and self._less(heap[child + 1], heap[child]):
                child += 1
            if not self._less(heap[child], item):
                break
            heap[index] = heap[child]
            heap[index].heap_index = index
            index = child
        heap[index] = item
        item.heap_index = index

    def _heap_push(self, flow):
        flow.heap_index = len(self.heap)
        self.heap.append(flow)
        self._heap_up(flow.heap_index)

    def _heap_pop(self):
        heap = self.heap
        root = heap[0]
        tail = heap.pop()
        root.heap_index = -1
        if heap:
            heap[0] = tail
            tail.heap_index = 0
            self._heap_down(0)
        return root

    def _heap_remove(self, flow):
        index = flow.heap_index
        if index < 0:
            return
        heap = self.heap
        tail = heap.pop()
        flow.heap_index = -1
        if index < len(heap):
            heap[index] = tail
            tail.heap_index = index
            if index and self._less(tail, heap[(index - 1) // 2]):
                self._heap_up(index)
            else:
                self._heap_down(index)

    def _heap_activity_changed(self, flow):
        # Packet times are nondecreasing, so an activity key can only grow.
        self._heap_down(flow.heap_index)

    def _fallback_class(self, flow):
        node = self.fallback
        prefix = flow.prefix
        while "class" not in node:
            feature = node["feature"]
            value = prefix[feature] if feature < len(prefix) else 0
            node = node["le"] if value <= node["threshold"] else node["gt"]
        return node["class"]

    def _decide(self, flow, cls, reason, rule, at, time, events):
        flow.cls = cls
        flow.reason = reason
        flow.rule = rule
        self._heap_remove(flow)
        events.append({"type": "decision", "flow": flow.id, "class": cls,
                       "reason": reason, "at": at, "time": time,
                       "rule": rule})

    def _advance(self, time, events):
        self.now = time
        expired = []
        while self.heap:
            root = self.heap[0]
            if time - root.last <= self.timeout:
                break
            expired.append(self._heap_pop())
        if expired:
            expired.sort(key=lambda flow: flow.id)
            for flow in expired:
                cls = self._fallback_class(flow)
                self._decide(flow, cls, "idle", None, flow.n, time, events)

    def _packet(self, record, events):
        time = record["time"]
        self._advance(time, events)
        flow = self.flows[record["flow"]]
        source = record["source"]
        if flow.forward is None:
            flow.forward = source
        feature = (record["length"] if source == flow.forward
                   else -record["length"])
        flow.n += 1
        flow.last = time
        if len(flow.prefix) < self.width:
            flow.prefix.append(feature)

        hits = 0
        if self.position_count:
            candidates = (((flow.state << 1) | self.first_mask) &
                          self.accept[feature + 2048])
            hits = candidates & self.terminal_mask
            # Terminal bits need not be carried into the next packet.  All
            # other set bits are precisely the continuable prefix states.
            flow.state = candidates ^ hits
        if flow.heap_index >= 0:
            self._heap_activity_changed(flow)

        best_rule = None
        best_priority = 0
        best_length = 0
        match_count = 0
        remaining = hits
        while remaining:
            low_bit = remaining & -remaining
            terminal = low_bit.bit_length() - 1
            rule_index = self.terminal_to_rule[terminal]
            rid, cls, priority, length, _terminal = self.rules[rule_index]
            events.append({"type": "match", "flow": flow.id, "rule": rid,
                           "start": flow.n - length, "end": flow.n})
            match_count += 1
            if (best_rule is None or priority > best_priority or
                    (priority == best_priority and length > best_length)):
                best_rule = (rid, cls)
                best_priority = priority
                best_length = length
            remaining ^= low_bit
        flow.matches += match_count

        if flow.reason is None:
            if best_rule is not None:
                self._decide(flow, best_rule[1], "key", best_rule[0],
                             flow.n, time, events)
            elif flow.n >= self.packet_limit:
                cls = self._fallback_class(flow)
                self._decide(flow, cls, "packet_limit", None,
                             flow.n, time, events)

    @staticmethod
    def _valid_flow(value):
        return _integer(value, 0, MAX_FLOW)

    @staticmethod
    def _valid_time(value):
        return _integer(value, 0, MAX_TIME)

    def _validate_timed(self, request, flow_required=False):
        if not self._valid_time(request["time"]):
            raise Invalid()
        if self.now is not None and request["time"] < self.now:
            raise Invalid()
        if flow_required and not self._valid_flow(request["flow"]):
            raise Invalid()

    def handle(self, request):
        if type(request) is not dict or "op" not in request:
            raise Invalid()
        _check_depth(request)
        op = request["op"]
        if type(op) is not str:
            raise Invalid()

        if op == "restore":
            if self.started or set(request) != {"op", "checkpoint"}:
                raise Invalid()
            self._restore(request["checkpoint"])
            self.started = True
            return []

        # Every request, including checkpoint and malformed attempts after a
        # successful first request, makes a later restore ineligible.
        self.started = True

        if op == "checkpoint":
            if set(request) != {"op"}:
                raise Invalid()
            return self._checkpoint()
        if op == "open":
            if set(request) != {"op", "flow", "time"}:
                raise Invalid()
            self._validate_timed(request, True)
            flow_id = request["flow"]
            if flow_id in self.flows or len(self.flows) >= 4096:
                raise Invalid()
            events = []
            self._advance(request["time"], events)
            flow = Flow(flow_id, request["time"])
            self.flows[flow_id] = flow
            self._heap_push(flow)
            return events
        if op == "tick":
            if set(request) != {"op", "time"}:
                raise Invalid()
            self._validate_timed(request)
            events = []
            self._advance(request["time"], events)
            return events
        if op == "close":
            if set(request) != {"op", "flow", "time"}:
                raise Invalid()
            self._validate_timed(request, True)
            flow_id = request["flow"]
            if flow_id not in self.flows:
                raise Invalid()
            events = []
            self._advance(request["time"], events)
            flow = self.flows[flow_id]
            if flow.reason is None:
                cls = self._fallback_class(flow)
                self._decide(flow, cls, "end", None, flow.n,
                             request["time"], events)
            events.append({"type": "closed", "flow": flow.id,
                           "packets": flow.n, "matches": flow.matches,
                           "class": flow.cls, "reason": flow.reason,
                           "rule": flow.rule})
            del self.flows[flow_id]
            return events
        if op == "chunk":
            if set(request) != {"op", "packets"}:
                raise Invalid()
            packets = request["packets"]
            if type(packets) is not list or len(packets) > 1024:
                raise Invalid()
            previous = self.now
            # Validate the entire chunk before producing any of its effects.
            for packet in packets:
                if not _exact_keys(packet, {"flow", "time", "source", "length"}):
                    raise Invalid()
                if (not self._valid_flow(packet["flow"]) or
                        packet["flow"] not in self.flows or
                        not self._valid_time(packet["time"]) or
                        not _integer(packet["source"], 0, 1) or
                        not _integer(packet["length"], 1, 2048)):
                    raise Invalid()
                if previous is not None and packet["time"] < previous:
                    raise Invalid()
                previous = packet["time"]
            events = []
            for packet in packets:
                self._packet(packet, events)
            return events
        raise Invalid()

    def _checkpoint(self):
        saved = []
        for flow_id in sorted(self.flows):
            flow = self.flows[flow_id]
            decision = None
            if flow.reason is not None:
                decision = [flow.cls, flow.reason, flow.rule]
            saved.append([flow.id, flow.last, flow.n, flow.matches,
                          flow.forward, flow.prefix, _encode_int(flow.state),
                          decision])
        return {"t": self.now, "f": saved}

    def _restore(self, value):
        # Checkpoints are opaque values produced by this implementation.  The
        # basic checks below also keep accidental incompatible values from
        # causing partial protocol output.
        if not _exact_keys(value, {"t", "f"}) or type(value["f"]) is not list:
            raise Invalid()
        now = value["t"]
        if now is not None and not self._valid_time(now):
            raise Invalid()
        flows = {}
        for item in value["f"]:
            if type(item) is not list or len(item) != 8:
                raise Invalid()
            flow_id, last, n, matches, forward, prefix, state, decision = item
            if (not self._valid_flow(flow_id) or flow_id in flows or
                    not self._valid_time(last) or
                    not _integer(n, 0, 1000000000000) or
                    not _integer(matches, 0, 1000000000000) or
                    not (forward is None or _integer(forward, 0, 1)) or
                    type(prefix) is not list or len(prefix) > self.width or
                    type(state) is not str):
                raise Invalid()
            if now is None or last > now:
                raise Invalid()
            restored = Flow(flow_id, last)
            restored.n = n
            restored.matches = matches
            restored.forward = forward
            restored.prefix = list(prefix)
            try:
                restored.state = int(state, 16)
            except ValueError:
                raise Invalid()
            if decision is not None:
                if type(decision) is not list or len(decision) != 3:
                    raise Invalid()
                restored.cls, restored.reason, restored.rule = decision
            flows[flow_id] = restored
        if len(flows) > 4096:
            raise Invalid()
        self.now = now
        self.flows = flows
        self.heap = []
        for flow_id in sorted(flows):
            flow = flows[flow_id]
            if flow.reason is None:
                self._heap_push(flow)


def _stream_main(path):
    # The evaluator supplies an unmodified successful compiler output.
    with open(path, "r", encoding="utf-8") as source:
        program = _loads(source.read())
    engine = Engine(program)
    stdin = sys.stdin.buffer
    stdout = sys.stdout.buffer
    while True:
        line = stdin.readline()
        if not line:
            return 0
        try:
            request = _loads(line.decode("utf-8"))
            result = engine.handle(request)
            if type(result) is dict:
                response = {"checkpoint": result}
            else:
                response = {"events": result}
        except (Invalid, ValueError, TypeError, KeyError, IndexError,
                UnicodeError, json.JSONDecodeError, RecursionError,
                OverflowError):
            stdout.write(b'{"error":"event"}\n')
            stdout.flush()
            return 2
        output = json.dumps(response, separators=(",", ":"),
                            ensure_ascii=True).encode("ascii")
        stdout.write(output + b"\n")
        stdout.flush()


def main():
    if len(sys.argv) == 2 and sys.argv[1] == "compile":
        return _compile_main()
    if len(sys.argv) == 3 and sys.argv[1] == "stream":
        return _stream_main(sys.argv[2])
    return 2


if __name__ == "__main__":
    sys.exit(main())
